from pypdf import PdfReader
import re
r=PdfReader('manuscript.pdf')
for i,p in enumerate(r.pages,1):
    text=p.extract_text()
    matches=[s for s in text.splitlines() if re.search(r'github|agreement|kappa|alpha|license|seed|significan|reproduc|conflict|340|checkpoint|reverse|code|release',s,re.I)]
    if matches: print('PAGE',i, '\\n'+'\\n'.join(matches))
links=[]
for i,p in enumerate(r.pages,1):
    for a in p.get('/Annots',[]):
        a=a.get_object()
        if '/A' in a:
            action=a['/A']
            if '/URI' in action and ('github' in str(action['/URI']).lower() or i<8): links.append((i,str(action['/URI'])))
print('LINKS',links)
PY"
